const listAllUsers = `-- name: ListAllUsers :many
SELECT
  id, username, email, created_at, updated_at, max_storage_bytes, data_limit_updated_at, consumed_storage_bytes
FROM
  chronicle_users
ORDER BY
  created_at DESC
`

func (q *sqlQuerier) ListAllUsers(ctx context.Context) ([]ChronicleUser, error) {
	rows, err := q.db.Query(ctx, listAllUsers)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ChronicleUser
	for rows.Next() {
		var i ChronicleUser
		if err := rows.Scan(
			&i.ID,
			&i.Username,
			&i.Email,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.MaxStorageBytes,
			&i.DataLimitUpdatedAt,
			&i.ConsumedStorageBytes,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

